import PageTour, { type TourStep } from './PageTour';
import { getLanguage } from '@/i18n/localize';

type View = 'projects' | 'rooms' | 'room-mj' | 'room-player';

export default function ApplicationTour({ view }: { view: View }) {
  const tr = (fr: string, en: string) => getLanguage() === 'en' ? en : fr;
  const steps: Record<View, TourStep[]> = {
    projects: [
      { target: 'project-create', title: tr('Créer un projet', 'Create a project'), body: tr('Un projet rassemble les créations d’une partie ou d’un univers. Commence avec Général ou crée ton propre projet avec Nouveau projet.', 'A project brings together creations for a game or setting. Start with General or create your own using New project.') },
      { target: '.studio-project-tile', title: tr('Ouvrir tes créations', 'Open your creations'), body: tr('Clique sur l’affiche d’un projet pour accéder à ses Héros, ses Cartes et ses Ressources : planches A4, couvertures et conversions d’images.', 'Click a project poster to access its Heroes, Cards and Resources: A4 sheets, covers and image conversions.') },
      { target: '.studio-project-tile', title: tr('Gérer et sauvegarder le projet', 'Manage and back up the project'), body: tr('Le menu de chaque projet permet de le gérer et de l’exporter. Tu peux aussi importer un fichier de projet. Tes créations sont conservées sur cet appareil : exporte-les pour les sauvegarder ou les transférer.', 'Each project menu lets you manage and export it. You can also import a project file. Creations are stored on this device: export them to back them up or transfer them.') },
      { target: 'application-menu', title: tr('Le menu de l’application', 'The app menu'), body: tr('Ce menu en haut à gauche est disponible partout dans l’application. Utilise-le pour retrouver tes projets et naviguer entre les différents espaces.', 'This top-left menu is available throughout the app. Use it to find your projects and navigate between sections.') },
      { target: 'application-search', title: tr('La recherche de l’application', 'App search'), body: tr('La recherche en haut à droite est disponible partout dans l’application. Saisis au moins trois caractères pour retrouver un projet, un héros, une carte ou une ressource, parmi tous tes projets.', 'Search at the top right is available throughout the app. Enter at least three characters to find a project, hero, card or resource across all your projects.') },
    ],
    rooms: [
      { target: 'room-create', title: tr('Créer une salle', 'Create a room'), body: tr('Crée une salle pour accueillir ta table comme maître du jeu. Sur mobile, utilise le bouton +. Tu peux ensuite partager une invitation et protéger l’accès par un mot de passe.', 'Create a room to host your table as game master. On mobile, use +. You can then share an invitation and protect access with a password.') },
      { target: 'room-list', title: tr('Retrouver ta salle', 'Find your room'), body: tr('Les salles en ligne apparaissent ici. Choisis celle de ta table pour la rejoindre. Si la liste est vide, tu peux créer une salle ou utiliser une invitation.', 'Online rooms appear here. Choose your table’s room to join it. If the list is empty, create a room or use an invitation.') },
      { target: 'room-join', title: tr('Rejoindre par invitation', 'Join by invitation'), body: tr('Avec Par identifiant, saisis le code ou le lien d’invitation reçu. Choisis ensuite ton pseudo et, si nécessaire, le mot de passe de la salle.', 'Use By ID to enter a room code or invitation link. Then choose your nickname and enter the room password if needed.') },
      { target: 'room-library', title: tr('Reprendre une salle', 'Resume a room'), body: tr('Tes salles enregistrées sur cet appareil permettent de reprendre une partie. Tu peux aussi importer une salle depuis un fichier .clapSalle.', 'Rooms saved on this device let you resume a game. You can also import a room from a .clapSalle file.') },
    ],
    'room-mj': [
      { target: 'room-management', title: tr('Inviter et gérer la table', 'Invite and manage your table'), body: tr('Gérer la salle regroupe l’invitation, les réglages et les actions de gestion. Partage le lien ou le QR code pour accueillir les joueurs.', 'Manage room contains invitations, settings and management actions. Share the link or QR code to welcome players.') },
      { target: 'room-players', title: tr('Les héros de la salle', 'Room heroes'), body: tr('Retrouve les joueurs et leurs héros. Tu peux attribuer une fiche, consulter les cartes et accompagner les actions de la table.', 'Find players and their heroes here. Assign a sheet, inspect cards and support your table’s actions.') },
      { target: 'room-private-cards', title: tr('Tes cartes privées', 'Your private cards'), body: tr('Ajoute les cartes utiles à la scène : rôles clés, figurants, pouvoirs ou véhicules. Cet espace reste visible uniquement par toi.', 'Add cards for the scene: key roles, extras, powers or vehicles. This area is visible only to you.') },
      { target: 'room-chat', title: tr('Discussion et jets', 'Chat and rolls'), body: tr('La discussion rassemble les messages et les résultats des jets. Sur mobile, l’onglet Discussion permet de l’ouvrir.', 'The chat brings together messages and roll results. On mobile, open it with the Discussion tab.') },
    ],
    'room-player': [
      { target: 'room-management', title: tr('Choisir ton héros', 'Choose your hero'), body: tr('Le menu ⋮ permet de choisir ou changer ton héros, de voir les héros de la salle et de retrouver les actions de la salle. Le MJ peut aussi t’attribuer une fiche.', 'Use the ⋮ menu to choose or change your hero, see room heroes and access room actions. The GM can also assign a sheet to you.') },
      { target: '.room-player-sheet', title: tr('Jouer avec ta fiche', 'Play with your sheet'), body: tr('Quand ton héros est attribué, clique sur les valeurs de sa fiche pour préparer tes jets. Dans Constantes, tu peux gérer ses blessures, son stress et ses chagrins.', 'Once your hero is assigned, click sheet values to prepare rolls. In Vitals, manage injuries, stress and grief.') },
      { target: 'hero-tabs', title: tr('Retrouver tes cartes', 'Find your cards'), body: tr('La rubrique Cartes liées donne accès aux cartes de ton héros. Sur mobile, les onglets de la fiche restent accessibles en bas de l’écran.', 'Linked cards gives access to your hero’s cards. On mobile, sheet tabs remain available at the bottom of the screen.') },
      { target: '.room-player-discussion', title: tr('Échanger avec la table', 'Talk to your table'), body: tr('Ouvre Discussion pour lire les messages et les résultats des jets ou écrire à la table. Les demandes de jets du MJ apparaissent dans ta fiche.', 'Open Discussion to read messages and roll results or write to your table. GM roll requests appear in your sheet.') },
    ],
  };
  return <PageTour page={view} customSteps={steps[view]} introTitle={view === 'projects' ? tr('Bienvenue dans l’application Clap & Role', 'Welcome to the Clap & Role app') : undefined} introBody={view === 'projects' ? tr('Prépare tes parties, crée tes héros et tes cartes, et organise tes créations par projet. Découvrons les principaux espaces de l’application.', 'Prepare games, create heroes and cards, and organize your creations by project. Let’s explore the app’s main sections.') : undefined} />;
}
